def run_v118(args):
    old = sys.argv[:]
    try:
        sys.argv = ["mfp3_v118_embedded.py"]
        if args.full:
            sys.argv.append("--full")

        g = {
            "__name__": "mfp3_v118_embedded",
            "__file__": "<embedded:v1.18>",
            "__builtins__": __builtins__,
        }
        # v1.8 executes the frozen v1.7 source under this synthetic name.
        # Python 3.10 dataclasses require it to exist in sys.modules.
        with registered_module("mfp3_frozen_v17_embedded"):
            exec(compile(V118_SOURCE, g["__file__"], "exec"), g, g)
            g["main"]()
    finally:
        sys.argv = old

