def now_utc():
    return datetime.now(timezone.utc).isoformat(timespec="seconds")

def fetch_bytes(url, timeout=15):
    req = urllib.request.Request(
        url,
        headers={
            "User-Agent": "Mozilla/5.0 MFP3-CausalResearch/1.19",
            "Accept": "text/csv,text/plain,*/*",
        },
    )
    with urllib.request.urlopen(req, timeout=timeout) as r:
        return r.read()

def cached_download(name, urls, max_age_hours=24):
    path = CACHE / name

    if path.exists():
        age = (
            datetime.now(timezone.utc).timestamp()
            - path.stat().st_mtime
        ) / 3600.0
        if age <= max_age_hours:
            return path, "cache"

    if isinstance(urls, str):
        urls = [urls]

    errors = []

    for url in urls:
        try:
            data = fetch_bytes(url)
            if len(data) < 20:
                raise ValueError("respuesta demasiado corta")
            path.write_bytes(data)
            return path, url
        except Exception as e:
            errors.append(f"{url}: {e!r}")

    if path.exists():
        return path, "stale_cache"

    raise RuntimeError(" | ".join(errors))

def perf(ret):
    r = pd.Series(ret).replace([np.inf, -np.inf], np.nan).fillna(0.0)

    if len(r) == 0:
        return {
            "observations": 0,
            "total_return": 0.0,
            "cagr": 0.0,
            "sharpe": 0.0,
            "sortino": 0.0,
            "hit_rate": 0.0,
            "max_drawdown": 0.0,
            "ann_vol": 0.0,
        }

    curve = (1 + r).cumprod()
    total = float(curve.iloc[-1] - 1.0)
    years = max(len(r) / 252.0, 1 / 252.0)
    cagr = float(curve.iloc[-1] ** (1.0 / years) - 1.0)
    vol = float(r.std() * np.sqrt(252))
    sharpe = float(r.mean() * 252 / vol) if vol > 1e-12 else 0.0
    downside = float(r[r < 0].std() * np.sqrt(252))
    sortino = (
        float(r.mean() * 252 / downside)
        if downside > 1e-12
        else 0.0
    )
    active = r[r != 0]
    hit_rate = float((active > 0).mean()) if len(active) else 0.0
    dd = curve / curve.cummax() - 1.0

    return {
        "observations": int(len(r)),
        "total_return": total,
        "cagr": cagr,
        "sharpe": sharpe,
        "sortino": sortino,
        "hit_rate": hit_rate,
        "max_drawdown": float(dd.min()),
        "ann_vol": vol,
    }

def utility(ret, turnover=None):
    p = perf(ret)

    t = 0.0
    if turnover is not None:
        t = float(pd.Series(turnover).fillna(0.0).sum())

    u = (
        p["sharpe"]
        + 0.40 * p["cagr"]
        - 0.60 * abs(p["max_drawdown"])
        - 0.010 * t
    )
    return u, p

def safe_name(x):
    return (
        str(x)
        .replace("^", "")
        .replace("=", "_")
        .replace("-", "_")
        .replace(".", "_")
        .replace(" ", "_")
        .lower()
    )

def robust_z(s, n=252):
    s = pd.to_numeric(s, errors="coerce")
    med = s.rolling(n, min_periods=max(40, n // 3)).median()
    mad = (s - med).abs().rolling(
        n, min_periods=max(40, n // 3)
    ).median()

    scale = 1.4826 * mad
    z = (s - med) / scale.replace(0, np.nan)
    return z.clip(-8, 8)

def safe_corr(a, b, min_n=40):
    z = pd.DataFrame({"a": a, "b": b}).dropna()

    if len(z) < min_n:
        return np.nan

    if z["a"].std() < 1e-12 or z["b"].std() < 1e-12:
        return np.nan

    return float(z["a"].rank().corr(z["b"].rank()))


