def extract_close(raw, ticker):
    if isinstance(raw.columns, pd.MultiIndex):
        l0 = raw.columns.get_level_values(0)
        l1 = raw.columns.get_level_values(1)

        if ticker in l1:
            d = raw.xs(ticker, axis=1, level=1)
        elif ticker in l0:
            d = raw[ticker]
        else:
            return None
    else:
        d = raw

    if "Close" not in d.columns:
        return None

    s = pd.to_numeric(d["Close"], errors="coerce").dropna()
    s.index = pd.to_datetime(s.index).tz_localize(None)
    return s.sort_index()

def download_market(status):
    raw = yf.download(
        MARKET_TICKERS,
        start=START,
        auto_adjust=True,
        progress=False,
        group_by="column",
        threads=True,
        timeout=30,
    )

    out = {}

    for t in MARKET_TICKERS:
        s = extract_close(raw, t)

        if s is not None and len(s):
            out[t] = s
            status[f"YF_{t}"] = {
                "ok": True,
                "rows": int(len(s)),
            }
        else:
            status[f"YF_{t}"] = {
                "ok": False,
                "rows": 0,
            }

    for required in TARGETS + ["CLP=X"]:
        if required not in out:
            raise RuntimeError(f"Serie esencial no disponible: {required}")

    return out

