def parse_fred_csv(path, series_id):
    df = pd.read_csv(path)

    if len(df.columns) < 2:
        raise ValueError("CSV FRED sin columnas suficientes")

    idx = pd.to_datetime(df.iloc[:, 0], errors="coerce")
    val = pd.to_numeric(df.iloc[:, -1], errors="coerce")

    s = pd.Series(val.to_numpy(), index=idx, name=series_id)
    return s[~s.index.isna()].dropna().sort_index()

def fred_series_resilient(series_id):
    urls = [
        (
            "https://fred.stlouisfed.org/graph/"
            f"fredgraph.csv?id={series_id}"
        ),
        (
            "https://fred.stlouisfed.org/series/"
            f"{series_id}/downloaddata/{series_id}.csv"
        ),
    ]

    path, used = cached_download(
        f"fred_{series_id}.csv",
        urls,
        max_age_hours=24,
    )

    return parse_fred_csv(path, series_id), used

def market_proxy_macro(market):
    # Proxies are deliberately labelled as proxies; they do not impersonate
    # the unavailable FRED series.
    idx = market["QQQ"].index
    out = {}

    def align(t):
        if t not in market:
            return pd.Series(np.nan, index=idx)
        return market[t].reindex(idx).ffill(limit=5)

    tnx = align("^TNX")
    irx = align("^IRX")
    tip = align("TIP")
    tlt = align("TLT")
    shy = align("SHY")
    hyg = align("HYG")
    uup = align("UUP")
    vix = align("^VIX")

    # ^TNX is 10-year yield x10 in Yahoo convention; scale is irrelevant after z.
    out["proxy_nominal10y"] = tnx
    out["proxy_curve_10y_3m"] = tnx - irx

    # Bond ETF relative returns as a rough real/duration condition proxy.
    out["proxy_real_rate_pressure"] = (
        -tip.pct_change(5)
        + tlt.pct_change(5)
    )

    # Credit / financial conditions proxies.
    out["proxy_credit_stress"] = (
        -(hyg.pct_change(5) - shy.pct_change(5))
    )
    out["proxy_financial_stress"] = (
        robust_z(vix, 252)
        + robust_z(
            -(hyg.pct_change(20) - tlt.pct_change(20)),
            252,
        )
    )

    out["proxy_usd"] = uup
    return out

def download_macro(status, market):
    series = {}
    for name, sid in FRED_SERIES.items():
        try:
            s, used = fred_series_resilient(sid)

            # Conservative release lag.
            lag_days = 4 if sid == "NFCI" else 1
            s.index = s.index + pd.Timedelta(days=lag_days)

            series[name] = s
            status[f"FRED_{sid}"] = {
                "ok": True,
                "rows": int(len(s)),
                "source": used,
                "lag_days": lag_days,
            }
        except Exception as e:
            status[f"FRED_{sid}"] = {
                "ok": False,
                "error": repr(e)[:300],
            }

    proxies = market_proxy_macro(market)
    for name, s in proxies.items():
        series[name] = s
        status[f"PROXY_{name}"] = {
            "ok": True,
            "rows": int(s.notna().sum()),
        }

    return series


def availability_records(status):
    """Describe the actual historical-data contract used by this run.

    Current public endpoints return today's revised history rather than the
    vintage that was visible on each historical decision date. The ledger is
    intentionally fail-closed: research may run, but promotion is blocked.
    """

    fallback_map = {
        "real10y": "proxy_real_rate_pressure",
        "curve10y2y": "proxy_curve_10y_3m",
        "nfci": "proxy_financial_stress",
        "breakeven10y": "none; feature unavailable on failure",
        "dgs2": "SHY inverse return",
        "dgs10": "proxy_nominal10y",
        "usd_broad": "UUP/proxy_usd",
    }
    records = []
    for name, sid in FRED_SERIES.items():
        info = status.get(f"FRED_{sid}", {})
        records.append(SourceRecord(
            source="FRED",
            variable=name,
            frequency="daily_or_weekly",
            release_lag=f"{info.get('lag_days', 'unknown')} calendar days",
            vintage_policy="current_revised_history",
            fallback=fallback_map[name],
            point_in_time=False,
        ))

    records.append(SourceRecord(
        source="CFTC",
        variable="copper_positioning",
        frequency="weekly",
        release_lag="3 calendar days from Tuesday report date",
        vintage_policy="current_public_history",
        fallback="none; feature unavailable on failure",
        point_in_time=False,
    ))
    records.append(SourceRecord(
        source="Yahoo Finance",
        variable="market_and_proxy_series",
        frequency="daily",
        release_lag="close t; decision executes next session",
        vintage_policy="current_adjusted_history",
        fallback="none for required targets",
        point_in_time=False,
    ))
    return records

