def cftc_copper(status):
    base = (
        f"https://publicreporting.cftc.gov/resource/"
        f"{CFTC_DATASET}.csv"
    )

    params = {
        "$limit": "50000",
        "$where": (
            "cftc_contract_market_code='"
            + CFTC_COPPER_CODE
            + "'"
        ),
        "$order": "report_date_as_yyyy_mm_dd",
    }

    url = base + "?" + urllib.parse.urlencode(params, safe="'= ")

    try:
        path, used = cached_download(
            "cftc_copper.csv",
            url,
            max_age_hours=24,
        )
        df = pd.read_csv(path)

        def find_col(*needles):
            for c in df.columns:
                low = str(c).lower()
                if all(n in low for n in needles):
                    return c
            return None

        date_col = find_col("report", "date")
        oi_col = find_col("open_interest", "all")
        mm_long = find_col("m_money", "long")
        mm_short = find_col("m_money", "short")
        prod_long = find_col("prod_merc", "long")
        prod_short = find_col("prod_merc", "short")
        swap_long = find_col("swap", "long")
        swap_short = find_col("swap", "short")

        needed = [
            date_col, oi_col,
            mm_long, mm_short,
            prod_long, prod_short,
            swap_long, swap_short,
        ]

        if any(c is None for c in needed):
            raise ValueError("Columnas CFTC esperadas no encontradas")

        idx = pd.to_datetime(df[date_col], errors="coerce")
        oi = pd.to_numeric(df[oi_col], errors="coerce").replace(0, np.nan)

        def num(c):
            return pd.to_numeric(df[c], errors="coerce")

        z = pd.DataFrame(index=idx)
        z["mm_net_oi"] = (
            (num(mm_long) - num(mm_short)) / oi
        ).to_numpy()
        z["prod_net_oi"] = (
            (num(prod_long) - num(prod_short)) / oi
        ).to_numpy()
        z["swap_net_oi"] = (
            (num(swap_long) - num(swap_short)) / oi
        ).to_numpy()
        z["open_interest"] = oi.to_numpy()

        z = z[~z.index.isna()].sort_index()

        # Tuesday positions are not treated as known until Friday.
        z.index = z.index + pd.Timedelta(days=3)

        for c in ["mm_net_oi", "prod_net_oi", "swap_net_oi"]:
            z[f"{c}_chg4w"] = z[c].diff(4)

        status["CFTC_COPPER"] = {
            "ok": True,
            "rows": int(len(z)),
            "source": used,
            "contract_code": CFTC_COPPER_CODE,
        }
        return z

    except Exception as e:
        status["CFTC_COPPER"] = {
            "ok": False,
            "error": repr(e)[:400],
        }
        return pd.DataFrame()

# ---------------------------------------------------------------------
# Align utility
# ---------------------------------------------------------------------

def align_level(s, idx, limit=None):
    union = s.index.union(idx)
    a = s.reindex(union).sort_index().ffill(limit=limit).reindex(idx)
    return pd.to_numeric(a, errors="coerce")

def market_ret(market, ticker, idx, n=1):
    if ticker not in market:
        return pd.Series(np.nan, index=idx)

    s = align_level(market[ticker], idx, limit=5)
    return s.pct_change(n)

def macro_level(macro, name, idx):
    if name not in macro:
        return pd.Series(np.nan, index=idx)

    s = macro[name]

    if s.index.equals(idx):
        return pd.to_numeric(s, errors="coerce")

    return align_level(s, idx)

# ---------------------------------------------------------------------
# Driver construction
# ---------------------------------------------------------------------

MECHANISMS = {
    "rate_real_shock":
        "tasas reales -> tasa de descuento/financiación -> valoración",
    "rate_nominal_shock":
        "Treasury corto -> expectativas monetarias -> descuento",
    "curve_shock":
        "curva -> ciclo/expectativas de crecimiento y política",
    "inflation_expectation_shock":
        "inflación implícita -> tasas/descuento/márgenes",
    "financial_stress_shock":
        "estrés financiero/crédito -> prima de riesgo y financiación",
    "vix_shock":
        "volatilidad implícita -> prima de riesgo",
    "usd_shock":
        "dólar global -> condiciones financieras/commodities",
    "fomc_rate_market_shock":
        "decisión/comunicación FOMC -> reajuste de tasas -> activos",
    "china_demand_shock":
        "actividad/riesgo China -> demanda esperada de cobre",
    "copper_positioning_shock":
        "posicionamiento especulativo -> presión/expectativas en cobre",
    "producer_positioning_shock":
        "cobertura productores -> expectativas/oferta del cobre",
    "copper_non_demand_shock":
        "movimiento cobre no explicado por China/USD/rates -> oferta/otros",
    "copper_terms_shock":
        "cobre vs petróleo -> términos de intercambio de Chile",
    "clp_shock":
        "USDCLP -> valoración local/condiciones financieras Chile",
    "global_risk_shock":
        "riesgo global/crédito -> flujos hacia activos de riesgo",
    "growth_breadth_shock":
        "growth vs broad market -> apetito por duración/tecnología",
    "credit_shock":
        "crédito HY -> condiciones financieras/risk appetite",
}

DRIVER_MAP = {
    "QQQ": [
        "rate_real_shock",
        "rate_nominal_shock",
        "curve_shock",
        "inflation_expectation_shock",
        "financial_stress_shock",
        "vix_shock",
        "usd_shock",
        "fomc_rate_market_shock",
        "growth_breadth_shock",
        "credit_shock",
        "global_risk_shock",
    ],
    "CPER": [
        "china_demand_shock",
        "usd_shock",
        "rate_real_shock",
        "financial_stress_shock",
        "vix_shock",
        "copper_positioning_shock",
        "producer_positioning_shock",
        "copper_non_demand_shock",
        "global_risk_shock",
    ],
    "ECH": [
        "china_demand_shock",
        "copper_terms_shock",
        "clp_shock",
        "rate_real_shock",
        "financial_stress_shock",
        "vix_shock",
        "usd_shock",
        "copper_non_demand_shock",
        "global_risk_shock",
    ],
}

def build_drivers(asset, market, macro, cot):
    idx = market[asset].index
    d = pd.DataFrame(index=idx)

    # Basic daily market changes.
    qqq1 = market_ret(market, "QQQ", idx, 1)
    spy1 = market_ret(market, "SPY", idx, 1)
    iwm1 = market_ret(market, "IWM", idx, 1)
    fxi1 = market_ret(market, "FXI", idx, 1)
    eem1 = market_ret(market, "EEM", idx, 1)
    copper1 = market_ret(market, "HG=F", idx, 1)
    gold1 = market_ret(market, "GC=F", idx, 1)
    oil1 = market_ret(market, "CL=F", idx, 1)
    hyg1 = market_ret(market, "HYG", idx, 1)
    tlt1 = market_ret(market, "TLT", idx, 1)
    shy1 = market_ret(market, "SHY", idx, 1)
    uup1 = market_ret(market, "UUP", idx, 1)
    clp1 = market_ret(market, "CLP=X", idx, 1)

    vix = (
        align_level(market["^VIX"], idx, limit=5)
        if "^VIX" in market
        else pd.Series(np.nan, index=idx)
    )

    # Macro/FRED or proxies.
    real10 = macro_level(macro, "real10y", idx)
    dgs2 = macro_level(macro, "dgs2", idx)
    curve = macro_level(macro, "curve10y2y", idx)
    breakeven = macro_level(macro, "breakeven10y", idx)
    nfci = macro_level(macro, "nfci", idx)
    usd_broad = macro_level(macro, "usd_broad", idx)

    proxy_real = macro_level(macro, "proxy_real_rate_pressure", idx)
    proxy_curve = macro_level(macro, "proxy_curve_10y_3m", idx)
    proxy_stress = macro_level(macro, "proxy_financial_stress", idx)
    proxy_credit = macro_level(macro, "proxy_credit_stress", idx)
    proxy_usd = macro_level(macro, "proxy_usd", idx)

    # Prefer actual FRED; fallback to proxies.
    real_change = real10.diff()
    if real_change.notna().sum() < 200:
        real_change = proxy_real.diff()

    nominal2_change = dgs2.diff()
    if nominal2_change.notna().sum() < 200:
        # SHY price falls when short yields rise; invert return.
        nominal2_change = -shy1

    curve_change = curve.diff()
    if curve_change.notna().sum() < 200:
        curve_change = proxy_curve.diff()

    breakeven_change = breakeven.diff()

    stress_change = nfci.diff()
    if stress_change.notna().sum() < 150:
        stress_change = proxy_stress.diff()

    dollar_change = usd_broad.pct_change()
    if dollar_change.notna().sum() < 200:
        dollar_change = uup1
    if dollar_change.notna().sum() < 200:
        dollar_change = proxy_usd.pct_change()

    # Standardized unexpected innovations.
    d["rate_real_shock"] = robust_z(real_change, 252)
    d["rate_nominal_shock"] = robust_z(nominal2_change, 252)
    d["curve_shock"] = robust_z(curve_change, 252)
    d["inflation_expectation_shock"] = robust_z(breakeven_change, 252)
    d["financial_stress_shock"] = robust_z(stress_change, 252)
    d["vix_shock"] = robust_z(vix.pct_change(), 252)
    d["usd_shock"] = robust_z(dollar_change, 252)

    # FOMC event gate. Rate-market move is used as shock proxy, not the action itself.
    fomc = pd.Series(0.0, index=idx)
    fomc.loc[fomc.index.intersection(FOMC_DECISION_DATES)] = 1.0
    d["fomc_rate_market_shock"] = d["rate_nominal_shock"] * fomc

    # China demand shock: China equity move relative to global/emerging markets.
    china_rel = (
        fxi1
        - 0.50 * eem1
        - 0.50 * spy1
    )
    d["china_demand_shock"] = robust_z(china_rel, 252)

    # Risk/credit.
    credit = hyg1 - shy1
    global_risk = (
        -robust_z(vix.pct_change(), 252)
        + robust_z(credit, 252)
        + robust_z(spy1, 252)
    ) / 3.0

    d["credit_shock"] = robust_z(credit, 252)
    d["global_risk_shock"] = global_risk

    # Growth breadth.
    d["growth_breadth_shock"] = robust_z(
        qqq1 - 0.50 * spy1 - 0.50 * iwm1,
        252,
    )

    # Chile.
    d["clp_shock"] = robust_z(-clp1, 252)  # positive = CLP strengthens
    d["copper_terms_shock"] = robust_z(copper1 - oil1, 252)

    # CFTC positioning.
    if not cot.empty:
        cz = (
            cot.reindex(cot.index.union(idx))
            .sort_index()
            .ffill()
            .reindex(idx)
        )

        d["copper_positioning_shock"] = robust_z(
            cz["mm_net_oi"].diff(),
            156,
        )
        d["producer_positioning_shock"] = robust_z(
            cz["prod_net_oi"].diff(),
            156,
        )
    else:
        d["copper_positioning_shock"] = np.nan
        d["producer_positioning_shock"] = np.nan

    # Heuristic decomposition: residual-like copper move after demand/USD/rates.
    # This is explicitly named NON-DEMAND, not "supply" because it is not a
    # structural supply identification.
    residual = (
        robust_z(copper1, 252)
        - 0.35 * d["china_demand_shock"]
        + 0.25 * d["usd_shock"]
        + 0.20 * d["rate_real_shock"]
    )

    d["copper_non_demand_shock"] = residual.clip(-8, 8)

    # Only pre-declared mechanisms are eligible.
    allowed = [x for x in DRIVER_MAP[asset] if x in d.columns]
    d = d[allowed]

    return d

# ---------------------------------------------------------------------
# Asset frame / baseline
# ---------------------------------------------------------------------

def build_asset_frame(asset, market):
    usd = market[asset]
    idx = usd.index
    fx = align_level(market["CLP=X"], idx, limit=5)
    clp = usd * fx

    x = pd.DataFrame(index=idx)
    r = clp.pct_change()

    x["price_clp"] = clp
    x["daily_ret_clp"] = r

    for n in [1, 5, 20, 60, 120]:
        x[f"self_ret{n}"] = clp.pct_change(n)

    for n in [20, 60]:
        x[f"self_vol{n}"] = r.rolling(n).std() * np.sqrt(252)

    x["self_z252"] = robust_z(clp, 252)

    for h in HORIZONS:
        entry = clp.shift(-1)
        exit_ = clp.shift(-(h + 1))
        fwd = exit_ / entry - 1.0
        x[f"fwd_ret_{h}"] = fwd

    return x

BASELINE_COLS = [
    "self_ret1",
    "self_ret5",
    "self_ret20",
    "self_ret60",
    "self_vol20",
    "self_z252",
]

# ---------------------------------------------------------------------
# Causal evidence tests
# ---------------------------------------------------------------------

def future_return(frame, h):
    return frame[f"fwd_ret_{h}"]

def past_return(frame, h):
    return frame["price_clp"].pct_change(h)

def event_effect(driver, target):
    z = pd.DataFrame({"d": driver, "y": target}).dropna()

    if len(z) < MIN_DRIVER_EVENTS:
        return {
            "n_hi": 0,
            "n_lo": 0,
            "event_spread": np.nan,
        }

    hi = z[z["d"] >= 1.0]["y"]
    lo = z[z["d"] <= -1.0]["y"]

    if len(hi) < 10 or len(lo) < 10:
        return {
            "n_hi": len(hi),
            "n_lo": len(lo),
            "event_spread": np.nan,
        }

    return {
        "n_hi": len(hi),
        "n_lo": len(lo),
        "event_spread": float(hi.mean() - lo.mean()),
    }

def discovery_driver_tests(frame, drivers, h, years):
    rows = []
    target = future_return(frame, h)
    past = past_return(frame, h)

    for name in drivers.columns:
        yearly = []
        yearly_p = []
        reverse_yearly = []
        placebo_yearly = []
        event_spreads = []

        for y in years:
            year_mask = frame.index.year == y
            mask = (
                year_mask
                & mature_label_mask(
                    frame.index,
                    horizon=h,
                    allowed=year_mask,
                ).to_numpy()
            )

            fwd_ic, fwd_p = safe_corr_pvalue(
                drivers.loc[mask, name],
                target.loc[mask],
                min_n=60,
            )

            driver_year = drivers.loc[mask, name]
            placebo_shift = max(h + 1, len(driver_year) // 3)
            placebo = pd.Series(
                np.roll(driver_year.to_numpy(), placebo_shift),
                index=driver_year.index,
            )
            placebo_ic = safe_corr(
                placebo,
                target.loc[mask],
                min_n=60,
            )

            # Endogeneity / reverse-direction diagnostic:
            # how strongly is today's "cause" associated with already-realized
            # past asset returns? A genuine predictor should not be dominated by this.
            rev_ic = safe_corr(
                drivers.loc[mask, name],
                past.loc[mask],
                min_n=60,
            )

            if pd.notna(fwd_ic):
                yearly.append(float(fwd_ic))
            if pd.notna(fwd_p):
                yearly_p.append(float(fwd_p))

            if pd.notna(rev_ic):
                reverse_yearly.append(float(rev_ic))
            if pd.notna(placebo_ic):
                placebo_yearly.append(float(placebo_ic))

            ev = event_effect(
                drivers.loc[mask, name],
                target.loc[mask],
            )
            if pd.notna(ev["event_spread"]):
                event_spreads.append(float(ev["event_spread"]))

        if len(yearly) < 3:
            continue

        mean_ic = float(np.mean(yearly))
        sign = 1.0 if mean_ic >= 0 else -1.0

        consistency = float(
            np.mean([
                np.sign(v) == np.sign(mean_ic)
                for v in yearly
                if v != 0
            ])
        ) if any(v != 0 for v in yearly) else 0.0

        reverse_ic = (
            float(np.mean(reverse_yearly))
            if reverse_yearly
            else 0.0
        )

        temporal_advantage = abs(mean_ic) - abs(reverse_ic)
        placebo_ic = (
            float(np.mean(placebo_yearly))
            if placebo_yearly
            else np.nan
        )
        placebo_advantage = (
            abs(mean_ic) - abs(placebo_ic)
            if pd.notna(placebo_ic)
            else np.nan
        )
        discovery_p = combined_pvalue(yearly_p)

        event_spread = (
            float(np.mean(event_spreads))
            if event_spreads
            else np.nan
        )

        # A permissive discovery gate; validation will be stricter.
        pre_fdr_gate = (
            abs(mean_ic) >= 0.025
            and consistency >= 2 / 3
            and temporal_advantage >= -0.015
            and pd.notna(placebo_advantage)
            and placebo_advantage >= 0.005
        )

        score = (
            abs(mean_ic)
            * consistency
            * max(0.05, 0.10 + temporal_advantage)
        )

        rows.append({
            "driver": name,
            "mechanism": MECHANISMS.get(name, ""),
            "discovery_ic": mean_ic,
            "direction": sign,
            "consistency": consistency,
            "reverse_ic": reverse_ic,
            "temporal_advantage": temporal_advantage,
            "placebo_ic": placebo_ic,
            "placebo_advantage": placebo_advantage,
            "discovery_p": discovery_p,
            "event_spread": event_spread,
            "pre_fdr_gate": bool(pre_fdr_gate),
            "accepted_discovery": False,
            "score": score,
        })

    tab = pd.DataFrame(rows)

    if tab.empty:
        return tab

    tab["n_hypotheses"] = int(len(tab))
    tab["discovery_q"] = benjamini_hochberg(tab["discovery_p"])
    tab["accepted_discovery"] = (
        tab["pre_fdr_gate"]
        & (tab["discovery_q"] <= DISCOVERY_FDR_Q)
    )
    tab.loc[~tab["accepted_discovery"], "score"] = 0.0

    return tab.sort_values(
        ["accepted_discovery", "score"],
        ascending=False,
    )

def validate_driver_tests(frame, drivers, h, discovery_tab, years):
    if discovery_tab.empty:
        return pd.DataFrame()

    target = future_return(frame, h)
    rows = []

    for r in discovery_tab[
        discovery_tab["accepted_discovery"]
    ].itertuples(index=False):

        vals = []
        pvals = []

        for y in years:
            year_mask = frame.index.year == y
            mask = (
                year_mask
                & mature_label_mask(
                    frame.index,
                    horizon=h,
                    allowed=year_mask,
                ).to_numpy()
            )
            ic, pvalue = safe_corr_pvalue(
                drivers.loc[mask, r.driver],
                target.loc[mask],
                min_n=60,
            )
            if pd.notna(ic):
                vals.append(float(ic))
            if pd.notna(pvalue):
                pvals.append(float(pvalue))

        if len(vals) < 2:
            continue

        mean_val = float(np.mean(vals))
        sign_survival = float(
            np.mean([
                np.sign(v)
                == np.sign(r.discovery_ic)
                for v in vals
                if v != 0
            ])
        ) if any(v != 0 for v in vals) else 0.0

        pre_validation_gate = (
            sign_survival >= 0.50
            and (
                mean_val * r.discovery_ic
            ) > 0
            and abs(mean_val) >= 0.010
        )

        rows.append({
            **r._asdict(),
            "validation_ic": mean_val,
            "validation_p": combined_pvalue(pvals),
            "validation_sign_survival": sign_survival,
            "pre_validation_gate": bool(pre_validation_gate),
            "accepted_validation": False,
            "validated_score": r.score * abs(mean_val) * max(0.25, sign_survival),
        })

    out = pd.DataFrame(rows)

    if out.empty:
        return out

    out["validation_n_hypotheses"] = int(len(out))
    out["validation_q"] = benjamini_hochberg(out["validation_p"])
    out["accepted_validation"] = (
        out["pre_validation_gate"]
        & (out["validation_q"] <= VALIDATION_FDR_Q)
    )
    out.loc[~out["accepted_validation"], "validated_score"] = 0.0

    return out.sort_values(
        ["accepted_validation", "validated_score"],
        ascending=False,
    ).head(MAX_CAUSES_PER_ASSET)

# ---------------------------------------------------------------------
# Baseline and causal model
# ---------------------------------------------------------------------

def ridge(alpha):
    return Pipeline([
        (
            "imp",
            SimpleImputer(
                strategy="median",
                add_indicator=True,
            ),
        ),
        ("sc", StandardScaler()),
        ("m", Ridge(alpha=alpha)),
    ])

def prediction_to_position(pred, train_target):
    scale = float(pd.Series(train_target).std())

    if not np.isfinite(scale) or scale < 1e-5:
        scale = 0.02

    score = np.tanh(pd.Series(pred) / scale)

    # long-only exposure
    return (0.50 + 0.50 * score).clip(0, 1)

def strategy_returns(position, daily_ret):
    target = pd.Series(position, index=daily_ret.index).fillna(0).clip(0, 1)

    # Decision at close t; held from next session.
    held = target.shift(1).fillna(0.0)

    turnover = held.diff().abs().fillna(held.abs())

    net = (
        held * daily_ret.fillna(0.0)
        - turnover * ONE_WAY_COST
    )
    return net, held, turnover

def fit_eval_model(
    train_frame,
    val_frame,
    train_drivers,
    val_drivers,
    h,
    accepted,
    alpha,
    causal=True,
):
    target = f"fwd_ret_{h}"

    cols = [c for c in BASELINE_COLS if c in train_frame.columns]

    if causal:
        causal_cols = [
            r.driver
            for r in accepted.itertuples(index=False)
            if r.accepted_validation
            and r.driver in train_drivers.columns
        ]

        Xtr = pd.concat(
            [
                train_frame[cols],
                train_drivers[causal_cols],
            ],
            axis=1,
        )
        Xva = pd.concat(
            [
                val_frame[cols],
                val_drivers[causal_cols],
            ],
            axis=1,
        )

        model_cols = list(Xtr.columns)
    else:
        Xtr = train_frame[cols]
        Xva = val_frame[cols]
        model_cols = cols

    mature = mature_label_mask(train_frame.index, horizon=h)
    ztr = pd.concat(
        [Xtr.loc[mature], train_frame.loc[mature, [target]]],
        axis=1,
    ).dropna(subset=[target])

    if len(ztr) < 400 or len(model_cols) < 3:
        return None

    m = ridge(alpha)
    m.fit(ztr[model_cols], ztr[target])

    pred = pd.Series(
        m.predict(Xva[model_cols]),
        index=val_frame.index,
    )

    pos = prediction_to_position(pred, ztr[target])

    net, held, turnover = strategy_returns(
        pos,
        val_frame["daily_ret_clp"],
    )

    u, p = utility(net, turnover)

    # Predictive correlation diagnostic.
    pred_ic = safe_corr(
        pred,
        val_frame[target],
        min_n=100,
    )

    return {
        "utility": u,
        "perf": p,
        "pred_ic": pred_ic,
        "columns": model_cols,
        "model": m,
        "train_target": ztr[target],
    }

# ---------------------------------------------------------------------
# Nested year evaluation
# ---------------------------------------------------------------------

def evaluate_year(asset, frame, drivers, test_year):
    discovery_years = [
        test_year - 5,
        test_year - 4,
        test_year - 3,
    ]
    validation_years = [
        test_year - 2,
        test_year - 1,
    ]

    required = discovery_years + validation_years + [test_year]

    for y in required:
        if np.sum(frame.index.year == y) < MIN_YEAR_OBS:
            return None

    discovery = frame[frame.index.year.isin(discovery_years)].copy()
    validation = frame[frame.index.year.isin(validation_years)].copy()
    test = frame[frame.index.year == test_year].copy()

    d_disc = drivers.reindex(discovery.index)
    d_val = drivers.reindex(validation.index)
    d_test = drivers.reindex(test.index)

    candidates = []

    for h in HORIZONS:
        disc = discovery_driver_tests(
            discovery,
            d_disc,
            h,
            discovery_years,
        )

        accepted = validate_driver_tests(
            validation,
            d_val,
            h,
            disc,
            validation_years,
        )

        if accepted.empty or not accepted["accepted_validation"].any():
            continue

        # Baseline vs causal. The causal model must add incremental validation utility.
        for alpha in RIDGE_ALPHAS:
            base = fit_eval_model(
                discovery,
                validation,
                d_disc,
                d_val,
                h,
                accepted,
                alpha,
                causal=False,
            )

            causal = fit_eval_model(
                discovery,
                validation,
                d_disc,
                d_val,
                h,
                accepted,
                alpha,
                causal=True,
            )

            if base is None or causal is None:
                continue

            incremental = causal["utility"] - base["utility"]

            candidates.append({
                "horizon": h,
                "alpha": alpha,
                "accepted": accepted,
                "causal": causal,
                "baseline": base,
                "incremental_utility": incremental,
            })

    if not candidates:
        return None

    # Prefer incremental value, but require usable absolute validation utility.
    best = max(
        candidates,
        key=lambda x: (
            x["incremental_utility"],
            x["causal"]["utility"],
        ),
    )

    # Gate: causes must improve validation over technical baseline.
    if best["incremental_utility"] <= 0:
        return {
            "asset": asset,
            "test_year": test_year,
            "status": "NO_INCREMENTAL_CAUSAL_VALUE",
            "horizon": best["horizon"],
            "alpha": best["alpha"],
            "incremental_utility": best["incremental_utility"],
            "accepted": best["accepted"],
            "daily_ret": pd.Series(0.0, index=test.index),
            "position": pd.Series(0.0, index=test.index),
            "turnover": pd.Series(0.0, index=test.index),
            "prediction": pd.Series(np.nan, index=test.index),
            "test_frame": test,
            "future_perf": perf(pd.Series(0.0, index=test.index)),
        }

    h = best["horizon"]
    alpha = best["alpha"]

    causal_driver_names = [
        r.driver
        for r in best["accepted"].itertuples(index=False)
        if r.accepted_validation
    ]

    cols_base = [c for c in BASELINE_COLS if c in frame.columns]

    # Retrain on all pre-test data, with labels that do not cross into test.
    pretest = frame[frame.index.year < test_year].copy()
    d_pre = drivers.reindex(pretest.index)

    # Positional purge follows the actual trading-session index. Calendar
    # BDay arithmetic is unsafe around holidays and can retain crossing labels.
    mask = mature_label_mask(pretest.index, horizon=h)

    Xpre = pd.concat(
        [
            pretest.loc[mask, cols_base],
            d_pre.loc[mask, causal_driver_names],
        ],
        axis=1,
    )

    Xtest = pd.concat(
        [
            test[cols_base],
            d_test[causal_driver_names],
        ],
        axis=1,
    )

    target = f"fwd_ret_{h}"

    tr = pd.concat(
        [
            Xpre,
            pretest.loc[mask, [target]],
        ],
        axis=1,
    ).dropna(subset=[target])

    if len(tr) < 500:
        return None

    m = ridge(alpha)
    m.fit(tr[Xpre.columns], tr[target])

    pred = pd.Series(
        m.predict(Xtest[Xpre.columns]),
        index=test.index,
    )

    pos = prediction_to_position(pred, tr[target])

    net, held, turnover = strategy_returns(
        pos,
        test["daily_ret_clp"],
    )

    fp = perf(net)

    # Future diagnostics for each accepted driver.
    future_rows = []

    for r in best["accepted"].itertuples(index=False):
        if not r.accepted_validation:
            continue

        future_ic = safe_corr(
            d_test[r.driver],
            test[target],
            min_n=60,
        )

        future_rows.append({
            **r._asdict(),
            "future_ic": future_ic,
            "future_sign_ok": (
                bool(
                    pd.notna(future_ic)
                    and np.sign(future_ic)
                    == np.sign(r.discovery_ic)
                )
            ),
        })

    future_tab = pd.DataFrame(future_rows)

    return {
        "asset": asset,
        "test_year": test_year,
        "status": "CAUSAL_VALUE_ACCEPTED",
        "horizon": h,
        "alpha": alpha,
        "incremental_utility": best["incremental_utility"],
        "accepted": future_tab,
        "daily_ret": net,
        "position": held,
        "turnover": turnover,
        "prediction": pred,
        "test_frame": test,
        "future_perf": fp,
    }

# ---------------------------------------------------------------------
# Walk-forward asset engine
# ---------------------------------------------------------------------

def run_asset(asset, frame, drivers):
    yearly = []
    driver_rows = []
    daily_parts = []

    latest = int(frame.index.max().year)

    for year in range(FIRST_TEST_YEAR, latest + 1):
        res = evaluate_year(asset, frame, drivers, year)

        if res is None:
            continue

        p = res["future_perf"]

        yearly.append({
            "asset": asset,
            "test_year": year,
            "status": res["status"],
            "horizon": res["horizon"],
            "alpha": res["alpha"],
            "incremental_utility": res["incremental_utility"],
            "future_return": p["total_return"],
            "future_sharpe": p["sharpe"],
            "future_drawdown": p["max_drawdown"],
        })

        accepted = res["accepted"]

        if isinstance(accepted, pd.DataFrame) and not accepted.empty:
            for r in accepted.itertuples(index=False):
                row = r._asdict()
                row.update({
                    "asset": asset,
                    "test_year": year,
                    "horizon": res["horizon"],
                })
                driver_rows.append(row)

        z = pd.DataFrame(index=res["test_frame"].index)
        z["asset"] = asset
        z["test_year"] = year
        z["status"] = res["status"]
        z["horizon"] = res["horizon"]
        z["prediction"] = res["prediction"]
        z["position"] = res["position"]
        z["turnover"] = res["turnover"]
        z["strategy_ret"] = res["daily_ret"]
        z["daily_ret_clp"] = res["test_frame"]["daily_ret_clp"]
        daily_parts.append(z)

        print(
            f"  {asset} {year}: "
            f"{res['status']} | H={res['horizon']} | "
            f"incremental={res['incremental_utility']:+.3f} | "
            f"futuro={p['total_return']:+.2%} | "
            f"Sharpe={p['sharpe']:.2f}"
        )

    return (
        pd.DataFrame(yearly),
        pd.DataFrame(driver_rows),
        pd.concat(daily_parts).sort_index()
        if daily_parts else pd.DataFrame(),
    )

# ---------------------------------------------------------------------
# Portfolio
# ---------------------------------------------------------------------

def causal_portfolio(daily, frames):
    idx = pd.DatetimeIndex(sorted(daily.index.unique()))

    strategy = pd.Series(0.0, index=idx)
    benchmark = pd.Series(0.0, index=idx)
    turnover = pd.Series(0.0, index=idx)

    for asset in TARGETS:
        z = daily[daily["asset"] == asset]

        sr = (
            z["strategy_ret"]
            .groupby(z.index)
            .last()
            .reindex(idx)
            .fillna(0.0)
        )

        strategy += MAX_ASSET_WEIGHT * sr

        at = (
            z["turnover"]
            .groupby(z.index)
            .last()
            .reindex(idx)
            .fillna(0.0)
        )
        turnover += MAX_ASSET_WEIGHT * at

        benchmark += (
            MAX_ASSET_WEIGHT
            * frames[asset]["daily_ret_clp"]
            .reindex(idx)
            .fillna(0.0)
        )

    out = pd.DataFrame(index=idx)
    out["causal_ret"] = strategy
    out["benchmark_ret"] = benchmark
    out["causal_turnover"] = turnover
    out["causal_transaction_cost"] = turnover * ONE_WAY_COST
    out["capital_causal"] = (
        INITIAL_CAPITAL * (1 + strategy).cumprod()
    )
    out["capital_benchmark"] = (
        INITIAL_CAPITAL * (1 + benchmark).cumprod()
    )
    return out

# ---------------------------------------------------------------------
# Evidence-gated blend with v1.14
# ---------------------------------------------------------------------

def month_firsts(index):
    s = pd.Series(np.arange(len(index)), index=index)

    return set(
        s.groupby([index.year, index.month])
        .head(1)
        .index
    )

def blend_return(frame, w):
    return (
        (1.0 - w) * frame["fusion_ret"]
        + w * frame["causal_ret"]
    )

def evidence_gated_fusion(causal_port, promotion_allowed):
    if not V14_DAILY.exists():
        return pd.DataFrame()

    v14 = pd.read_csv(
        V14_DAILY,
        index_col=0,
        parse_dates=True,
    ).sort_index()

    v14.index = pd.to_datetime(v14.index).tz_localize(None)

    common = causal_port.index.intersection(v14.index)

    if len(common) < 500:
        return pd.DataFrame()

    x = pd.DataFrame(index=common)

    x["causal_ret"] = causal_port.loc[common, "causal_ret"]
    x["causal_turnover"] = causal_port.loc[common, "causal_turnover"]
    x["causal_transaction_cost"] = causal_port.loc[
        common, "causal_transaction_cost"
    ]
    x["benchmark_ret"] = causal_port.loc[common, "benchmark_ret"]
    x["fusion_ret"] = v14.loc[common, "fusion_ret"]
    x["v17_ret"] = v14.loc[common, "v17_ret"]

    firsts = month_firsts(x.index)

    weights = pd.Series(0.0, index=x.index)
    bootstrap_passes = pd.Series(False, index=x.index)
    current = 0.0
    current_bootstrap = False

    for i, dt in enumerate(x.index):
        if i < 504:
            weights.loc[dt] = current
            continue

        if dt in firsts:
            hist = x.iloc[:i]

            rows = []

            for window in BLEND_WINDOWS:
                z = hist.tail(window)

                if len(z) < 220:
                    continue

                causal_perf = perf(z["causal_ret"])
                v14_perf = perf(z["fusion_ret"])

                # Engine evidence gate.
                engine_ok = (
                    causal_perf["sharpe"] > 0.25
                    and causal_perf["total_return"] > -0.05
                )
                bootstrap = None
                bootstrap_ok = False
                if promotion_allowed and engine_ok:
                    bootstrap = paired_block_bootstrap(
                        z["causal_ret"],
                        z["fusion_ret"],
                        block_size=BOOTSTRAP_BLOCK_SIZE,
                        samples=BOOTSTRAP_SAMPLES,
                        seed=BOOTSTRAP_SEED + i + window,
                        minimum_probability=BOOTSTRAP_MIN_PROBABILITY,
                    )
                    bootstrap_ok = bootstrap.passes

                for w in CAUSAL_BLEND_WEIGHTS:
                    ret = blend_return(z, w)
                    u, _ = utility(ret)

                    base_u, _ = utility(z["fusion_ret"])

                    # New engine receives weight only if the blend improves v1.14
                    # on past OOS history. Zero is always eligible.
                    accepted = (
                        w == 0.0
                        or (
                            promotion_allowed
                            and
                            engine_ok
                            and bootstrap_ok
                            and u > base_u + 0.005
                        )
                    )

                    rows.append({
                        "window": window,
                        "weight": w,
                        "utility": u,
                        "base_utility": base_u,
                        "bootstrap_passes": bootstrap_ok if w > 0 else False,
                        "bootstrap_probability_positive": (
                            bootstrap.probability_positive
                            if bootstrap is not None else 0.0
                        ),
                        "bootstrap_lower_95_annualized_delta": (
                            bootstrap.lower_95_annualized_delta
                            if bootstrap is not None else 0.0
                        ),
                        "accepted": accepted,
                    })

            tab = pd.DataFrame(rows)

            if len(tab):
                eligible = tab[tab["accepted"]]

                if len(eligible):
                    best = eligible.sort_values(
                        "utility",
                        ascending=False,
                    ).iloc[0]

                    target = float(best["weight"])
                    current_bootstrap = bool(best["bootstrap_passes"])

                    # Slow promotion / fast demotion.
                    if target > current:
                        current = 0.60 * current + 0.40 * target
                    else:
                        current = target

        weights.loc[dt] = current
        bootstrap_passes.loc[dt] = current_bootstrap

    x["causal_weight"] = weights
    x["bootstrap_gate_passed"] = bootstrap_passes
    x["v14_weight"] = 1.0 - weights
    x["blend_turnover"] = weights.diff().abs().fillna(weights.abs())
    x["blend_transaction_cost"] = x["blend_turnover"] * ONE_WAY_COST

    x["causal_fusion_ret_before_overlay_cost"] = (
        x["v14_weight"] * x["fusion_ret"]
        + x["causal_weight"] * x["causal_ret"]
    )
    x["causal_fusion_ret"] = (
        x["causal_fusion_ret_before_overlay_cost"]
        - x["blend_transaction_cost"]
    )
    x["reported_turnover"] = (
        x["causal_weight"] * x["causal_turnover"]
        + x["blend_turnover"]
    )

    x["capital_causal_fusion"] = (
        INITIAL_CAPITAL
        * (1 + x["causal_fusion_ret"]).cumprod()
    )

    return x

