def metrics_table(causal_port, fusion):
    rows = []

    if len(fusion):
        rows.extend([
            {
                "name": "CAUSAL_FUSION_CHALLENGER",
                **perf(fusion["causal_fusion_ret"]),
                "turnover": float(fusion["reported_turnover"].sum()),
                "transaction_cost": float(
                    (
                        fusion["causal_weight"]
                        * fusion["causal_transaction_cost"]
                        + fusion["blend_transaction_cost"]
                    ).sum()
                ),
            },
            {
                "name": "V14_ADAPTIVE_FUSION_REFERENCE",
                **perf(fusion["fusion_ret"]),
                "turnover": np.nan,
                "transaction_cost": np.nan,
            },
            {
                "name": "V17_REFERENCE_COMMON_WINDOW",
                **perf(fusion["v17_ret"]),
                "turnover": np.nan,
                "transaction_cost": np.nan,
            },
            {
                "name": "CAUSAL_ENGINE_REFERENCE",
                **perf(fusion["causal_ret"]),
                "turnover": float(fusion["causal_turnover"].sum()),
                "transaction_cost": float(
                    fusion["causal_transaction_cost"].sum()
                ),
            },
            {
                "name": "BENCHMARK_COMMON_WINDOW",
                **perf(fusion["benchmark_ret"]),
                "turnover": np.nan,
                "transaction_cost": np.nan,
            },
        ])
    else:
        rows.extend([
            {
                "name": "CAUSAL_ENGINE_REFERENCE",
                **perf(causal_port["causal_ret"]),
                "turnover": float(causal_port["causal_turnover"].sum()),
                "transaction_cost": float(
                    causal_port["causal_transaction_cost"].sum()
                ),
            },
            {
                "name": "BENCHMARK_COMMON_WINDOW",
                **perf(causal_port["benchmark_ret"]),
                "turnover": np.nan,
                "transaction_cost": np.nan,
            },
        ])

    return pd.DataFrame(rows)

def current_drivers(yearly, drivers):
    if yearly.empty:
        return pd.DataFrame()

    latest = int(yearly["test_year"].max())
    rows = []

    for asset in TARGETS:
        y = yearly[
            (yearly["asset"] == asset)
            & (yearly["test_year"] == latest)
        ]

        if y.empty:
            continue

        r = y.iloc[-1]

        d = drivers[
            (drivers["asset"] == asset)
            & (drivers["test_year"] == latest)
        ].copy()

        if len(d):
            if "validated_score" in d:
                d = d.sort_values("validated_score", ascending=False)

            items = []

            for x in d.head(8).itertuples(index=False):
                future = getattr(x, "future_ic", np.nan)

                items.append(
                    f"{x.driver} "
                    f"[D={x.discovery_ic:+.3f}; "
                    f"V={x.validation_ic:+.3f}; "
                    f"F={future:+.3f}]"
                )

            top = " | ".join(items)
        else:
            top = "NINGUNA"

        rows.append({
            "asset": asset,
            "research_year": latest,
            "status": r["status"],
            "horizon": int(r["horizon"]),
            "incremental_utility": float(r["incremental_utility"]),
            "historical_future_return": float(r["future_return"]),
            "historical_future_sharpe": float(r["future_sharpe"]),
            "top_causal_drivers": top,
        })

    return pd.DataFrame(rows)

