def run_causal_lab():
    ensure_lab_dirs()
    status = {}

    print("[v1.19] Descargando mercados...")
    market = download_market(status)

    print("[v1.19] Obteniendo macro/FRED + proxies...")
    macro = download_macro(status, market)

    print("[v1.19] Obteniendo CFTC cobre...")
    cot = cftc_copper(status)

    records = availability_records(status)
    promotion_allowed, promotion_blockers = promotion_eligibility(records)
    point_in_time_allowed = promotion_allowed
    point_in_time_blockers = list(promotion_blockers)
    ledger_frame(records).to_csv(
        AVAILABILITY_CSV,
        index=False,
        encoding="utf-8-sig",
    )
    status["PROMOTION_GATE_POINT_IN_TIME"] = {
        "ok": promotion_allowed,
        "blockers": promotion_blockers,
        "policy": "fail_closed",
    }

    SOURCE_STATUS_JSON.write_text(
        json.dumps(
            {
                "updated_at_utc": now_utc(),
                "sources": status,
            },
            indent=2,
            ensure_ascii=False,
        ),
        encoding="utf-8",
    )

    frames = {}
    driver_frames = {}

    for asset in TARGETS:
        print(f"[v1.19] Construyendo causas candidatas {asset}...")
        frames[asset] = build_asset_frame(asset, market)
        driver_frames[asset] = build_drivers(
            asset,
            market,
            macro,
            cot,
        )

    RUN_MANIFEST_JSON.write_text(
        json.dumps(
            {
                "created_at_utc": now_utc(),
                "version": "v1.19-methodology-foundation",
                "entrypoint_sha256": file_sha256(Path(__file__)),
                "random_seed": None,
                "configuration": {
                    "start": START,
                    "first_test_year": FIRST_TEST_YEAR,
                    "horizons": HORIZONS,
                    "ridge_alphas": RIDGE_ALPHAS,
                    "one_way_cost": ONE_WAY_COST,
                    "max_asset_weight": MAX_ASSET_WEIGHT,
                    "discovery_fdr_q": DISCOVERY_FDR_Q,
                    "validation_fdr_q": VALIDATION_FDR_Q,
                    "bootstrap_block_size": BOOTSTRAP_BLOCK_SIZE,
                    "bootstrap_samples": BOOTSTRAP_SAMPLES,
                    "bootstrap_min_probability": BOOTSTRAP_MIN_PROBABILITY,
                    "bootstrap_seed": BOOTSTRAP_SEED,
                },
                "promotion_allowed": promotion_allowed,
                "promotion_blockers": promotion_blockers,
                "inputs": {
                    "market_sha256": mapping_fingerprint(market),
                    "macro_sha256": mapping_fingerprint(macro),
                    "cftc_sha256": (
                        pandas_fingerprint(cot) if not cot.empty else None
                    ),
                    "market_rows": {
                        name: int(len(series)) for name, series in market.items()
                    },
                },
                "features": {
                    asset: pandas_fingerprint(driver_frames[asset])
                    for asset in TARGETS
                },
            },
            indent=2,
            ensure_ascii=False,
        ),
        encoding="utf-8",
    )

    yearly_parts = []
    driver_parts = []
    daily_parts = []

    print("\n[v1.19] Causal nested walk-forward...")

    for asset in TARGETS:
        y, d, daily = run_asset(
            asset,
            frames[asset],
            driver_frames[asset],
        )

        if len(y):
            yearly_parts.append(y)

        if len(d):
            driver_parts.append(d)

        if len(daily):
            daily_parts.append(daily)

    if not yearly_parts or not daily_parts:
        promotion_allowed = False
        promotion_blockers = list(promotion_blockers)
        promotion_blockers.append("insufficient_oos_results")
        promotion_blockers.append("bootstrap_evidence_unavailable")
        bootstrap_gate_passed = False
        yearly = pd.DataFrame(
            columns=["asset", "research_year", "status"]
        )
        drivers = pd.DataFrame(
            columns=["asset", "research_year", "driver", "status"]
        )
        causal_port = pd.DataFrame(
            columns=[
                "causal_ret",
                "causal_turnover",
                "causal_transaction_cost",
            ]
        )
        fusion = pd.DataFrame(
            columns=[
                "causal_fusion_ret",
                "fusion_ret",
                "causal_ret",
                "causal_weight",
                "v14_weight",
                "bootstrap_gate_passed",
            ]
        )
        metrics = pd.DataFrame([
            {
                "name": "CAUSAL_ENGINE_NO_EVIDENCE",
                **perf(pd.Series(dtype=float)),
                "turnover": 0.0,
                "transaction_cost": 0.0,
            }
        ])
        current = pd.DataFrame(
            columns=["asset", "driver", "status"]
        )
    else:
        yearly = pd.concat(yearly_parts, ignore_index=True)

        drivers = (
            pd.concat(driver_parts, ignore_index=True)
            if driver_parts else pd.DataFrame()
        )

        daily = pd.concat(daily_parts).sort_index()

        causal_port = causal_portfolio(daily, frames)

        fusion = evidence_gated_fusion(
            causal_port,
            promotion_allowed=promotion_allowed,
        )

        bootstrap_gate_passed = bool(
            len(fusion)
            and "bootstrap_gate_passed" in fusion
            and bool(fusion["bootstrap_gate_passed"].iloc[-1])
        )
        promotion_allowed = point_in_time_allowed and bootstrap_gate_passed
        if not bootstrap_gate_passed:
            promotion_blockers = list(promotion_blockers)
            promotion_blockers.append("bootstrap_evidence_unavailable")

        metrics = metrics_table(causal_port, fusion)

        current = current_drivers(yearly, drivers)

    status["PROMOTION_GATE_POINT_IN_TIME"] = {
        "ok": point_in_time_allowed,
        "blockers": point_in_time_blockers,
        "policy": "fail_closed",
    }
    status["PROMOTION_GATE_BLOCK_BOOTSTRAP"] = {
        "ok": bootstrap_gate_passed,
        "blockers": (
            [] if bootstrap_gate_passed
            else ["bootstrap_evidence_unavailable"]
        ),
        "policy": "fail_closed",
    }
    SOURCE_STATUS_JSON.write_text(
        json.dumps(
            {
                "updated_at_utc": now_utc(),
                "sources": status,
            },
            indent=2,
            ensure_ascii=False,
        ),
        encoding="utf-8",
    )
    run_manifest = json.loads(
        RUN_MANIFEST_JSON.read_text(encoding="utf-8")
    )
    run_manifest.update({
        "completed_at_utc": now_utc(),
        "promotion_allowed": promotion_allowed,
        "promotion_blockers": promotion_blockers,
        "point_in_time_gate_passed": point_in_time_allowed,
        "bootstrap_gate_passed": bootstrap_gate_passed,
        "result_rows": {
            "yearly": int(len(yearly)),
            "drivers": int(len(drivers)),
            "daily": int(len(causal_port)),
            "fusion": int(len(fusion)),
        },
    })
    RUN_MANIFEST_JSON.write_text(
        json.dumps(run_manifest, indent=2, ensure_ascii=False),
        encoding="utf-8",
    )

    yearly.to_csv(
        YEARLY_CSV,
        index=False,
        encoding="utf-8-sig",
    )

    drivers.to_csv(
        DRIVERS_CSV,
        index=False,
        encoding="utf-8-sig",
    )

    causal_port.to_csv(
        ENGINE_DAILY_CSV,
        encoding="utf-8-sig",
    )

    if len(fusion):
        fusion.to_csv(
            FUSION_DAILY_CSV,
            encoding="utf-8-sig",
        )

    metrics.to_csv(
        METRICS_CSV,
        index=False,
        encoding="utf-8-sig",
    )

    current.to_csv(
        CURRENT_CSV,
        index=False,
        encoding="utf-8-sig",
    )

    causal_weight = (
        float(fusion["causal_weight"].iloc[-1])
        if len(fusion)
        else 0.0
    )

    STATE_JSON.write_text(
        json.dumps(
            {
                "last_completed_utc": now_utc(),
                "version": "v1.19",
                "latest_causal_weight": causal_weight,
                "latest_v14_weight": 1.0 - causal_weight,
                "promotion_allowed": promotion_allowed,
                "promotion_blockers": promotion_blockers,
                "point_in_time_gate_passed": point_in_time_allowed,
                "bootstrap_gate_passed": bootstrap_gate_passed,
            },
            indent=2,
        ),
        encoding="utf-8",
    )

    return (
        yearly,
        drivers,
        causal_port,
        fusion,
        metrics,
        current,
        status,
    )

# ---------------------------------------------------------------------
# Cadence
# ---------------------------------------------------------------------

def causal_due(force=False):
    if force or not STATE_JSON.exists():
        return True

    try:
        state = json.loads(STATE_JSON.read_text(encoding="utf-8"))
        last = pd.Timestamp(state["last_completed_utc"])

        if last.tzinfo is None:
            last = last.tz_localize("UTC")
        else:
            last = last.tz_convert("UTC")

        return (
            pd.Timestamp.now(tz="UTC") - last
        ).days >= RUN_EVERY_DAYS

    except Exception:
        return True

